# Detect cycle
def has_cycle(head):
    slow, fast = head, head
    while fast and fast.next:
        slow = slow.next
        fast = fast.next.next
        if slow == fast:
            return True
    return False

# Find cycle start (Floyd's)
def cycle_start(head):
    slow = fast = head
    while fast and fast.next:
        slow, fast = slow.next, fast.next.next
        if slow == fast:
            break
    else:
        return None  # no cycle
    slow = head
    while slow != fast:
        slow, fast = slow.next, fast.next
    return slow

# Find middle of linked list
def find_middle(head):
    slow, fast = head, head
    while fast and fast.next:
        slow = slow.next
        fast = fast.next.next
    return slow

from collections import deque

def bfs(graph, start, end=None):
    visited = {start}
    queue = deque([(start, 0)])   # (node, distance)
    while queue:
        node, dist = queue.popleft()
        if node == end:
            return dist
        for neighbor in graph[node]:
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, dist + 1))
    return -1  # not reachable

# Level-order tree traversal
def level_order(root):
    if not root:
        return []
    result, queue = [], deque([root])
    while queue:
        level = []
        for _ in range(len(queue)):
            node = queue.popleft()
            level.append(node.val)
            if node.left:  queue.append(node.left)
            if node.right: queue.append(node.right)
        result.append(level)
    return result

# Multi-source BFS (e.g. all 0s spread simultaneously)
def multi_source_bfs(grid):
    queue = deque()
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == 0:
                queue.append((r, c, 0))
    while queue:
        r, c, dist = queue.popleft()
        for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and grid[nr][nc] == 1:
                grid[nr][nc] = dist + 1
                queue.append((nr, nc, dist + 1))

# Recursive DFS on graph
def dfs(graph, node, visited=None):
    if visited is None:
        visited = set()
    visited.add(node)
    # process node
    for neighbor in graph[node]:
        if neighbor not in visited:
            dfs(graph, neighbor, visited)
    return visited

# Iterative DFS (explicit stack)
def dfs_iterative(graph, start):
    visited, stack = set(), [start]
    while stack:
        node = stack.pop()
        if node not in visited:
            visited.add(node)
            # process node
            stack.extend(graph[node])
    return visited

# Tree in-order traversal (iterative)
def inorder(root):
    result, stack, curr = [], [], root
    while curr or stack:
        while curr:
            stack.append(curr)
            curr = curr.left
        curr = stack.pop()
        result.append(curr.val)
        curr = curr.right
    return result

def backtrack(result, current, choices, start=0):
    # Base case, valid complete solution
    if is_complete(current):
        result.append(list(current))
        return

    for i in range(start, len(choices)):
        # Pruning
        if not is_valid(current, choices[i]):
            continue
        # Choose
        current.append(choices[i])
        # Explore
        backtrack(result, current, choices, i + 1)  # i+1 to avoid reuse; i to allow reuse
        # Unchoose (backtrack)
        current.pop()

# Subsets
def subsets(nums):
    result = []
    def bt(start, curr):
        result.append(list(curr))
        for i in range(start, len(nums)):
            bt(i + 1, curr + [nums[i]])
    bt(0, [])
    return result

# Permutations
def permutations(nums):
    result = []
    def bt(curr, remaining):
        if not remaining:
            result.append(curr[:])
        for i in range(len(remaining)):
            bt(curr + [remaining[i]], remaining[:i] + remaining[i+1:])
    bt([], nums)
    return result

