# DFS flood-fill
def dfs(grid, r, c, visited=None):
    if visited is None: visited = set()
    if (r < 0 or r >= len(grid) or c < 0 or c >= len(grid[0])
            or grid[r][c] == '0' or (r, c) in visited):
        return
    visited.add((r, c))
    for dr, dc in DIRS:
        dfs(grid, r + dr, c + dc, visited)

