# Python shortcut using OrderedDict
class LRUCache:
    def __init__(self, capacity):
        self.cap = capacity
        self.cache = OrderedDict()

    def get(self, key):
        if key not in self.cache:
            return -1
        self.cache.move_to_end(key)
        return self.cache[key]

    def put(self, key, value):
        if key in self.cache:
            self.cache.move_to_end(key)
        self.cache[key] = value
        if len(self.cache) > self.cap:
            self.cache.popitem(last=False)

# From-scratch implementation (doubly linked list + dict)
class Node:
    def __init__(self, k=0, v=0):
        self.k, self.v = k, v
        self.prev = self.next = None

class LRUCacheScratch:
    def __init__(self, capacity):
        self.cap = capacity
        self.map = {}
        self.head = Node()   # dummy head (LRU end)
        self.tail = Node()   # dummy tail (MRU end)
        self.head.next, self.tail.prev = self.tail, self.head

    def _remove(self, node):
        node.prev.next, node.next.prev = node.next, node.prev

    def _insert_tail(self, node):
        node.prev, node.next = self.tail.prev, self.tail
        self.tail.prev.next = self.tail.prev = node

    def get(self, key):
        if key not in self.map: return -1
        self._remove(self.map[key])
        self._insert_tail(self.map[key])
        return self.map[key].v

    def put(self, key, value):
        if key in self.map: self._remove(self.map[key])
        self.map[key] = Node(key, value)
        self._insert_tail(self.map[key])
        if len(self.map) > self.cap:
            lru = self.head.next
            self._remove(lru)
            del self.map[lru.k]

# Cyclic sort, numbers 1..n
def cyclic_sort(nums):
    i = 0
    while i < len(nums):
        j = nums[i] - 1      # correct 0-indexed position
        if nums[i] != nums[j]:
            nums[i], nums[j] = nums[j], nums[i]
        else:
            i += 1
    return nums

# Find the missing number (1..n)
def find_missing(nums):
    cyclic_sort(nums)
    for i, num in enumerate(nums):
        if num != i + 1:
            return i + 1
    return len(nums) + 1

# Find the duplicate number
def find_duplicate(nums):
    i = 0
    while i < len(nums):
        j = nums[i] - 1
        if nums[i] != i + 1:
            if nums[i] != nums[j]:
                nums[i], nums[j] = nums[j], nums[i]
            else:
                return nums[i]
        else:
            i += 1
    return -1

