# Bitmask DP (enumerate all subsets)
def subset_sum(nums, target):
    n = len(nums)
    for mask in range(1 << n):    # 2^n subsets
        total = sum(nums[i] for i in range(n) if mask >> i & 1)
        if total == target:
            return [nums[i] for i in range(n) if mask >> i & 1]

