class BIT:
    def __init__(self, n):
        self.n = n
        self.tree = [0] * (n + 1)

    def update(self, i, delta=1):
        """Add delta to index i (1-indexed)."""
        while i <= self.n:
            self.tree[i] += delta
            i += i & (-i)      # move to parent

    def query(self, i):
        """Prefix sum [1..i] (1-indexed)."""
        s = 0
        while i > 0:
            s += self.tree[i]
            i -= i & (-i)      # move to lower significant bit
        return s

    def range_query(self, l, r):
        return self.query(r) - self.query(l - 1)

# Count inversions using BIT
def count_inversions(arr):
    compressed = {v: i+1 for i, v in enumerate(sorted(set(arr)))}
    bit = BIT(len(arr))
    inv = 0
    for num in reversed(arr):           # process right to left
        idx = compressed[num]
        inv += bit.query(idx - 1)       # count smaller elements to the right
        bit.update(idx)
    return inv

# 2D BIT
class BIT2D:
    def __init__(self, m, n):
        self.m, self.n = m, n
        self.tree = [[0]*(n+1) for _ in range(m+1)]
    def update(self, r, c, v=1):
        i = r
        while i <= self.m:
            j = c
            while j <= self.n:
                self.tree[i][j] += v; j += j&-j
            i += i&-i
    def query(self, r, c):
        s, i = 0, r
        while i: j=c;
        while i:
            j = c
            while j: s += self.tree[i][j]; j -= j&-j
            i -= i&-i
        return s

def max_subarray(nums):
    best = curr = nums[0]
    for x in nums[1:]:
        curr = max(x, curr + x)
        best = max(best, curr)
    return best

# With indices
def max_subarray_idx(nums):
    best = curr = nums[0]
    start = end = temp_start = 0
    for i in range(1, len(nums)):
        if nums[i] > curr + nums[i]:
            curr = nums[i]; temp_start = i
        else:
            curr += nums[i]
        if curr > best:
            best = curr; start = temp_start; end = i
    return best, start, end

# Maximum circular subarray = max(kadane, total - min_subarray)
def max_circular(nums):
    def kadane(a):
        best = curr = a[0]
        for x in a[1:]: curr = max(x, curr+x); best = max(best, curr)
        return best
    def min_sub(a):
        worst = curr = a[0]
        for x in a[1:]: curr = min(x, curr+x); worst = min(worst, curr)
        return worst
    total = sum(nums)
    wrapped = total - min_sub(nums)
    return max(kadane(nums), wrapped) if wrapped != 0 else kadane(nums)

def sort_colors(nums):
    """Sort array of 0s, 1s, 2s in place."""
    low = mid = 0
    high = len(nums) - 1
    while mid <= high:
        if nums[mid] == 0:
            nums[low], nums[mid] = nums[mid], nums[low]
            low += 1; mid += 1
        elif nums[mid] == 1:
            mid += 1
        else:                          # nums[mid] == 2
            nums[mid], nums[high] = nums[high], nums[mid]
            high -= 1
