# Generic 3-way partition around pivot
def three_way_partition(arr, pivot):
    low = mid = 0
    high = len(arr) - 1
    while mid <= high:
        if arr[mid] < pivot:
            arr[low], arr[mid] = arr[mid], arr[low]
            low += 1; mid += 1
        elif arr[mid] == pivot:
            mid += 1
        else:
            arr[mid], arr[high] = arr[high], arr[mid]
            high -= 1
    return low, mid    # [0..low) < pivot, [low..mid) == pivot, [mid..] > pivot

import random

def reservoir_sample(stream, k):
    """Pick k items uniformly at random from an iterator."""
    reservoir = []
    for i, item in enumerate(stream):
        if i < k:
            reservoir.append(item)
        else:
            j = random.randint(0, i)      # random index in [0..i]
            if j < k:
                reservoir[j] = item       # replace with probability k/(i+1)
    return reservoir

# k=1: pick one element uniformly at random
def random_node(head):
    """Pick a random node from a linked list in O(n) time O(1) space."""
    result, i = head, 1
    node = head.next
    while node:
        i += 1
        if random.randint(1, i) == 1:
            result = node
        node = node.next
    return result
